{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Investment — {{BUSINESS_NAME}}</title>
  <meta name="description" content="Practical, integrated session options for busy adults seeking balanced health and clarity.">
  <style>
    :root{--bg:#fbfbfa;--muted:#6b6b6b;--accent:#2b6b5b;--card:#ffffff;--glass:rgba(255,255,255,0.6)}
    *{box-sizing:border-box}
    body{font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial; margin:0; color:#111; background:linear-gradient(180deg,var(--bg),#f3f6f5); min-height:100vh;}
    header{display:flex;align-items:center;justify-content:space-between;padding:22px 28px;position:sticky;top:0;background:rgba(255,255,255,0.6);backdrop-filter:blur(6px);border-bottom:1px solid #eee}
    .brand{display:flex;gap:12px;align-items:center}
    .logo{width:44px;height:44px;border-radius:8px;background:linear-gradient(135deg,var(--accent),#1f4f3e);display:grid;place-items:center;color:white;font-weight:700}
    nav a{margin:0 10px;color:var(--muted);text-decoration:none;font-size:15px}
    nav a.active{color:var(--accent);font-weight:600}
    main{max-width:980px;margin:36px auto;padding:18px}
    .hero{display:grid;grid-template-columns:1fr;gap:18px;align-items:center}
    .panel{background:var(--card);border-radius:12px;padding:20px;box-shadow:0 6px 18px rgba(20,30,30,0.05)}
    h1{margin:0 0 8px;font-size:28px}
    p.lead{margin:0;color:var(--muted)}
    .cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin-top:18px}
    .card{padding:18px;border-radius:10px;background:linear-gradient(180deg,var(--glass),#fff);border:1px solid #eee}
    .price{font-size:20px;color:var(--accent);font-weight:700}
    .muted{color:var(--muted);font-size:14px}
    footer{max-width:980px;margin:36px auto;padding:18px;color:var(--muted);font-size:13px}

    /* Session Planner */
    .planner{display:grid;grid-template-columns:1fr 320px;gap:18px;margin-top:22px}
    .planner .form{padding:18px}
    label{display:block;font-size:13px;margin:10px 0 6px}
    input[type=text],select,textarea{width:100%;padding:10px;border-radius:8px;border:1px solid #e6e6e6}
    textarea{min-height:90px}
    .controls{display:flex;gap:10px;align-items:center;margin-top:12px}
    button.btn{background:var(--accent);color:white;padding:10px 14px;border-radius:8px;border:0;cursor:pointer}
    .output{padding:14px;background:#f7fffb;border-radius:8px;border:1px dashed #dbeee4}
    pre{white-space:pre-wrap;margin:0}

    /* reveal animation */
    .reveal{opacity:0;transform:translateY(12px);transition:opacity .6s ease,transform .6s ease}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion: reduce){.reveal{transition:none}}

    .meta{display:flex;justify-content:space-between;align-items:center}
    .pill{background:#eef6f2;color:var(--accent);padding:6px 10px;border-radius:999px;font-weight:600}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">HM</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="services.html">Offerings</a>
      <a href="approach.html">Philosophy</a>
      <a href="pricing.html" class="active">Investment</a>
      <a href="about.html">About</a>
      <a href="book.html">Book A Day</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main>
    <section class="hero panel" aria-labelledby="service-title">
      <div>
        <h1 id="service-title">Options for focused, integrative care</h1>
        <p class="lead">Choose a pace and depth that fits your schedule — from a decisive single-day intensive to a paced integration pathway.</p>
      </div>
      <div class="meta">
        <div class="pill">Evidence-minded • Whole-context</div>
        <div class="muted">Phone: {{PHONE}} • {{CITY}}, {{STATE}}</div>
      </div>
    </section>

    <section class="panel reveal" data-reveal>
      <h2 style="margin-top:0">Programs and fees</h2>
      <div class="cards">
        <div class="card">
          <div style="display:flex;justify-content:space-between;align-items:center">
            <div>
              <strong>Focused Day</strong>
              <div class="muted" style="margin-top:6px">A single intensive session to clarify priorities and leave with an action plan.</div>
            </div>
            <div style="text-align:right">
              <div class="price">$950</div>
              <div class="muted">8–10 hour focused day</div>
            </div>
          </div>
          <ul style="margin-top:12px;color:var(--muted);padding-left:18px">
            <li>Comprehensive intake & focused interventions</li>
            <li>One concise plan with daily practices</li>
            <li>Email follow-up within 7 days</li>
          </ul>
        </div>

        <div class="card">
          <div style="display:flex;justify-content:space-between;align-items:center">
            <div>
              <strong>Integration Series</strong>
              <div class="muted" style="margin-top:6px">Three sessions over 8 weeks to test small changes and refine what fits.</div>
            </div>
            <div style="text-align:right">
              <div class="price">$1,800</div>
              <div class="muted">3 x 60–90 min</div>
            </div>
          </div>
          <ul style="margin-top:12px;color:var(--muted);padding-left:18px">
            <li>Stepwise implementation & metrics</li>
            <li>Short check-ins and adjustments</li>
            <li>Personalized toolkit</li>
          </ul>
        </div>

        <div class="card">
          <div style="display:flex;justify-content:space-between;align-items:center">
            <div>
              <strong>VIP Path</strong>
              <div class="muted" style="margin-top:6px">More hands-on collaboration for complex needs and coordinated supports.</div>
            </div>
            <div style="text-align:right">
              <div class="price">Custom</div>
              <div class="muted">Bespoke timeline</div>
            </div>
          </div>
          <ul style="margin-top:12px;color:var(--muted);padding-left:18px">
            <li>Priority scheduling & coordination</li>
            <li>Multi-modal planning and referrals</li>
            <li>Flexible check-ins and metrics</li>
          </ul>
        </div>
      </div>
    </section>

    <section class="panel reveal" data-reveal style="margin-top:18px">
      <h2 style="margin-top:0">Is this right for you?</h2>
      <p class="muted">We focus on measurable, practical adjustments rather than promises of cure. If you want clear next steps, tailored tracking, and a clinician who considers lifestyle, mindset, and medical context together, pick a program that matches the time and support you prefer.</p>
    </section>

    <section class="panel reveal" data-reveal style="margin-top:18px">
      <h2 style="margin-top:0">Session Planner</h2>
      <div class="planner">
        <form class="form" id="plannerForm" onsubmit="return false;">
          <label for="concern">Primary concern</label>
          <input id="concern" name="concern" type="text" placeholder="e.g., chronic fatigue, stress, insomnia">

          <label for="length">Preferred session style</label>
          <select id="length" name="length">
            <option>Single Focused Day (8-10h)</option>
            <option>One 60–90 minute visit</option>
            <option>Integration Series (3 visits)</option>
            <option>VIP Path (custom)</option>
          </select>

          <label>Modalities you'd like included</label>
          <div style="display:flex;gap:8px;flex-wrap:wrap">
            <label style="font-size:13px"><input type="checkbox" name="mods" value="Nutrition"> Nutrition</label>
            <label style="font-size:13px"><input type="checkbox" name="mods" value="Movement"> Movement</label>
            <label style="font-size:13px"><input type="checkbox" name="mods" value="Sleep"> Sleep support</label>
            <label style="font-size:13px"><input type="checkbox" name="mods" value="Stress"> Stress tools</label>
            <label style="font-size:13px"><input type="checkbox" name="mods" value="Supplements"> Supplements review</label>
          </div>

          <label for="goal">Top target for the next 8 weeks</label>
          <input id="goal" name="goal" type="text" placeholder="What would success look like?">

          <div class="controls">
            <button class="btn" id="buildBtn">Build plan</button>
            <button class="btn" id="copyBtn" type="button">Copy summary</button>
            <div style="margin-left:auto;color:var(--muted);font-size:13px">Free preview</div>
          </div>
        </form>

        <aside style="padding:14px">
          <div class="output">
            <strong style="display:block;margin-bottom:8px">Plan summary</strong>
            <pre id="planOutput">Complete the form and press "Build plan" to see a clear, exportable summary.</pre>
          </div>
        </aside>
      </div>
    </section>

  </main>

  <footer>
    <div>{{BUSINESS_NAME}} • {{EMAIL}} • {{PHONE}}</div>
  </footer>

  <script>
    // Scroll reveal
    (function(){
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const targets = document.querySelectorAll('[data-reveal]');
      if(prefersReduced){ targets.forEach(el=>el.classList.add('visible')) ; return }
      const obs = new IntersectionObserver((entries)=>{
        entries.forEach(e=>{
          if(e.isIntersecting){ e.target.classList.add('visible'); obs.unobserve(e.target) }
        })
      },{threshold:0.12});
      targets.forEach(t=>{ t.classList.add('reveal'); obs.observe(t) });
    })();

    // Session Planner logic
    (function(){
      const form = document.getElementById('plannerForm');
      const buildBtn = document.getElementById('buildBtn');
      const copyBtn = document.getElementById('copyBtn');
      const output = document.getElementById('planOutput');

      function collect(){
        const data = {};
        data.concern = form.concern.value.trim() || 'Not specified';
        data.length = form.length.value;
        data.goal = form.goal.value.trim() || 'Goal not specified';
        const mods = Array.from(form.querySelectorAll('input[name="mods"]:checked')).map(i=>i.value);
        data.mods = mods.length?mods.join(', '):'None selected';
        return data;
      }

      function makeSummary(d){
        return [
          'Personalized session plan',
          '-------------------------',
          'Primary concern: ' + d.concern,
          'Chosen session style: ' + d.length,
          'Priority target (8 weeks): ' + d.goal,
          'Preferred modalities: ' + d.mods,
          '',
          'Suggested next steps:',
          '- Baseline measures & brief intake',
          '- Two small behavioral tests in first 2 weeks',
          '- One clearly tracked metric (e.g., sleep hours, energy diary)',
          '',
          'Notes: This is an educational plan and not a medical guarantee. For medical concerns, follow up with a licensed clinician.'
        ].join('\n');
      }

      buildBtn.addEventListener('click', function(e){
        e.preventDefault();
        const data = collect();
        output.textContent = makeSummary(data);
      });

      copyBtn.addEventListener('click', function(){
        const text = output.textContent || '';
        if(!text) return;
        navigator.clipboard && navigator.clipboard.writeText(text).then(()=>{
          const prev = copyBtn.textContent;
          copyBtn.textContent = 'Copied';
          setTimeout(()=>copyBtn.textContent = prev,1200);
        }).catch(()=>{ alert('Copy failed — select and copy manually.'); });
      });
    })();
  </script>
</body>
</html>"} 
{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>About — {{BUSINESS_NAME}}</title>
  <meta name="description" content="Who we are and how we work — clear, integrative care shaped for busy people.">
  <style>
    :root{--bg:#ffffff;--muted:#586166;--accent:#2b6b5b}
    *{box-sizing:border-box}
    body{font-family:system-ui,-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica,Arial; margin:0;color:#0b0b0b;background:linear-gradient(180deg,#fff,#f6fbfa)}
    header{display:flex;justify-content:space-between;align-items:center;padding:20px 26px;background:transparent}
    .logo{width:44px;height:44px;border-radius:9px;background:linear-gradient(135deg,var(--accent),#1f4f3e);display:grid;place-items:center;color:white;font-weight:700}
    nav a{margin:0 8px;color:var(--muted);text-decoration:none}
    main{max-width:920px;margin:28px auto;padding:18px}
    .intro{display:flex;gap:18px;align-items:flex-start}
    .panel{background:#ffffff;border-radius:12px;padding:18px;box-shadow:0 8px 20px rgba(18,30,30,0.04)}
    h1{margin:0 0 6px}
    .muted{color:var(--muted)}
    .timeline{display:flex;flex-direction:column;gap:12px;margin-top:14px}
    .step{display:flex;gap:12px;align-items:flex-start}
    .dot{width:12px;height:12px;border-radius:50%;background:var(--accent);margin-top:6px}
    .contact{margin-top:18px;padding:14px;background:#f8fffb;border-radius:8px}

    .reveal{opacity:0;transform:translateY(8px);transition:opacity .6s ease,transform .6s ease}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion: reduce){.reveal{transition:none}}

    /* small details */
    .values{display:flex;gap:10px;flex-wrap:wrap;margin-top:12px}
    .value{background:#f1fbf8;padding:8px 12px;border-radius:999px;color:var(--accent);font-weight:700}

  </style>
</head>
<body>
  <header>
    <div style="display:flex;gap:12px;align-items:center">
      <div class="logo">HM</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="services.html">Offerings</a>
      <a href="approach.html">Philosophy</a>
      <a href="pricing.html">Investment</a>
      <a href="about.html" style="color:var(--accent);font-weight:600">About</a>
      <a href="book.html">Book</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main>
    <section class="panel reveal" data-reveal>
      <h1>About our work</h1>
      <p class="muted">We combine practical medical knowledge with lifestyle and behavioral supports to help you move toward clearer days. Our focus is on collaborative planning, simple tracking, and changes that fit your life.</p>
      <div class="values" aria-hidden>
        <span class="value">Curious</span>
        <span class="value">Evidence-aware</span>
        <span class="value">Practical</span>
      </div>
    </section>

    <section class="panel reveal" data-reveal style="margin-top:18px">
      <h2 style="margin-top:0">How we approach a day with you</h2>
      <div class="timeline">
        <div class="step">
          <div class="dot"></div>
          <div>
            <strong>1. Focused intake</strong>
            <div class="muted">A structured conversation to map what matters most and reasonable first tests.</div>
          </div>
        </div>
        <div class="step">
          <div class="dot"></div>
          <div>
            <strong>2. Clear plan</strong>
            <div class="muted">A short list of prioritized, measurable steps you can try right away.</div>
          </div>
        </div>
        <div class="step">
          <div class="dot"></div>
          <div>
            <strong>3. Rapid feedback</strong>
            <div class="muted">Timely check-ins to iterate, adapt, and keep what works.</div>
          </div>
        </div>
      </div>
    </section>

    <section class="panel reveal" data-reveal style="margin-top:18px">
      <h2 style="margin-top:0">Meet the clinician</h2>
      <p class="muted">Clinical lead blends conventional training with lifestyle-focused strategies. Emphasis is on listening, evidence-informed options, and step-by-step implementation rather than one-size-fits-all answers.</p>
      <div style="display:flex;gap:14px;margin-top:12px;align-items:center">
        <div style="width:96px;height:96px;border-radius:12px;background:linear-gradient(135deg,var(--accent),#225d48);display:grid;place-items:center;color:white;font-weight:700">Dr</div>
        <div>
          <div style="font-weight:700">Clinical Lead</div>
          <div class="muted">Board-certified clinician • Integrative training • Years of practice translating evidence into everyday routines</div>
        </div>
      </div>
    </section>

    <section class="panel reveal" data-reveal style="margin-top:18px">
      <h2 style="margin-top:0">Session Planner</h2>
      <p class="muted">Quickly sketch an approach you can bring to your visit or use to decide which program fits best.</p>
      <div style="margin-top:12px">
        <!-- Small embedded planner: condensed version -->
        <form id="miniPlanner" onsubmit="return false;">
          <label for="mConcern">Primary concern</label>
          <input id="mConcern" name="mConcern" type="text" placeholder="e.g., stress, gut issues">
          <label style="margin-top:8px" for="mStyle">Preferred intensity</label>
          <select id="mStyle">
            <option>One 60–90 min visit</option>
            <option>Integration Series</option>
            <option>Focused Day</option>
          </select>
          <div style="display:flex;gap:8px;margin-top:10px">
            <button class="btn" id="miniBuild" style="background:var(--accent);color:white;padding:8px 12px;border-radius:8px;border:0">Preview</button>
            <button class="btn" id="miniCopy" type="button" style="background:#e6f6ef;color:var(--accent);">Copy</button>
          </div>
        </form>
        <pre id="miniOut" style="background:#fbfffc;padding:10px;border-radius:8px;margin-top:10px;color:var(--muted)">Use the form above and press Preview.</pre>
      </div>
    </section>

  </main>

  <footer style="max-width:920px;margin:28px auto;padding:10px;color:var(--muted);font-size:13px">{{BUSINESS_NAME}} • {{EMAIL}} • {{PHONE}}</footer>

  <script>
    // Reveal
    (function(){
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const els = document.querySelectorAll('[data-reveal]');
      if(prefersReduced){ els.forEach(e=>e.classList.add('visible')); return }
      const obs = new IntersectionObserver((entries)=>{ entries.forEach(en=>{ if(en.isIntersecting){ en.target.classList.add('visible'); obs.unobserve(en.target) } }) },{threshold:0.1});
      els.forEach(el=>{ el.classList.add('reveal'); obs.observe(el) });
    })();

    // Mini planner
    (function(){
      const form = document.getElementById('miniPlanner');
      const out = document.getElementById('miniOut');
      const miniBuild = document.getElementById('miniBuild');
      const miniCopy = document.getElementById('miniCopy');

      function build(){
        const concern = document.getElementById('mConcern').value.trim() || 'Not specified';
        const style = document.getElementById('mStyle').value;
        const text = ['Quick plan preview','---------------','Concern: '+concern,'Style: '+style,'','Suggested: Choose one measurable metric, try two small adjustments in week 1, schedule a short check-in within 2 weeks.'].join('\n');
        out.textContent = text; return text;
      }

      miniBuild.addEventListener('click', function(e){ e.preventDefault(); build(); });
      miniCopy.addEventListener('click', function(){ const t = out.textContent; if(!t) return; navigator.clipboard && navigator.clipboard.writeText(t).then(()=>{ miniCopy.textContent='Copied'; setTimeout(()=>miniCopy.textContent='Copy',900) }).catch(()=>alert('Copy failed')) });
    })();
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Book — {{BUSINESS_NAME}}</title>
  <meta name="description" content="Schedule a session or a focused day. Choose a format that fits your needs.">
  <style>
    :root{--bg:#f6fffb;--muted:#546168;--accent:#2b6b5b}
    *{box-sizing:border-box}
    body{font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial; margin:0;background:linear-gradient(180deg,var(--bg),#fff);color:#081018}
    header{display:flex;justify-content:space-between;align-items:center;padding:18px 24px}
    .logo{width:44px;height:44px;border-radius:9px;background:linear-gradient(135deg,var(--accent),#194f3f);display:grid;place-items:center;color:white;font-weight:700}
    nav a{margin:0 8px;color:var(--muted);text-decoration:none}
    main{max-width:900px;margin:26px auto;padding:18px}
    .panel{background:white;padding:18px;border-radius:12px;box-shadow:0 8px 18px rgba(14,22,20,0.04)}
    label{display:block;margin-top:10px;font-size:14px}
    input,select,textarea{width:100%;padding:10px;border-radius:8px;border:1px solid #e8f0ec}
    button.cta{background:var(--accent);color:white;padding:10px 14px;border-radius:10px;border:0;cursor:pointer;margin-top:12px}

    .reveal{opacity:0;transform:translateY(10px);transition:opacity .6s ease,transform .6s ease}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion: reduce){.reveal{transition:none}}

    .summary{background:#f8fffb;border-radius:8px;padding:12px;margin-top:12px;border:1px dashed #dbeee4}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;gap:12px;align-items:center">
      <div class="logo">HM</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="services.html">Offerings</a>
      <a href="pricing.html">Investment</a>
      <a href="about.html">About</a>
      <a href="book.html" style="color:var(--accent);font-weight:600">Book A Day</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main>
    <section class="panel reveal" data-reveal>
      <h1 style="margin:0 0 8px">Schedule a visit</h1>
      <p class="muted">Pick the session type and a few details to get a tailored appointment summary. We'll confirm availability after you submit.</p>

      <form id="bookForm" onsubmit="return false;" style="margin-top:12px">
        <label for="type">Session type</label>
        <select id="type" required>
          <option>One 60–90 minute visit</option>
          <option>Focused Day (8–10 hours)</option>
          <option>Integration Series (3 visits)</option>
          <option>VIP Path (custom)</option>
        </select>

        <label for="name">Your name</label>
        <input id="name" type="text" placeholder="Full name" required>

        <label for="email">Email</label>
        <input id="email" type="text" placeholder="you@domain.com" required>

        <label for="phone">Phone</label>
        <input id="phone" type="text" placeholder="Optional">

        <label for="date">Preferred date or range</label>
        <input id="date" type="text" placeholder="e.g., March 15 or mid-May">

        <label for="notes">Brief notes (what you want to focus on)</label>
        <textarea id="notes" placeholder="A few sentences is fine"></textarea>

        <div style="display:flex;gap:10px;align-items:center">
          <button class="cta" id="genBtn">Generate booking summary</button>
          <button class="cta" id="sendBtn" type="button" style="background:#fff;color:var(--accent);border:1px solid #e6f3ec">Send request</button>
          <div style="margin-left:auto;color:var(--muted);font-size:13px">We will confirm availability by email.</div>
        </div>
      </form>

      <div class="summary" id="bookingSummary" aria-live="polite">Complete the form and press "Generate booking summary". You can copy the result or click Send request to open your default email client with the summary prefilled.</div>

    </section>
  </main>

  <footer style="max-width:900px;margin:26px auto;padding:12px;color:var(--muted);font-size:13px">{{BUSINESS_NAME}} • {{PHONE}} • {{EMAIL}}</footer>

  <script>
    (function(){
      // reveal
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const nodes = document.querySelectorAll('[data-reveal]');
      if(prefersReduced){ nodes.forEach(n=>n.classList.add('visible')); }
      else{ const obs = new IntersectionObserver((entries)=>{ entries.forEach(en=>{ if(en.isIntersecting){ en.target.classList.add('visible'); obs.unobserve(en.target) } }) },{threshold:0.08}); nodes.forEach(n=>{ n.classList.add('reveal'); obs.observe(n) }); }

      // booking logic
      const genBtn = document.getElementById('genBtn');
      const sendBtn = document.getElementById('sendBtn');
      const out = document.getElementById('bookingSummary');

      function build(){
        const d = {
          type: document.getElementById('type').value,
          name: document.getElementById('name').value.trim() || 'Name not provided',
          email: document.getElementById('email').value.trim() || 'Email not provided',
          phone: document.getElementById('phone').value.trim() || 'Phone not provided',
          date: document.getElementById('date').value.trim() || 'No date preference',
          notes: document.getElementById('notes').value.trim() || 'No notes provided'
        };
        const txt = [
          'Booking summary for {{BUSINESS_NAME}}',
          '-------------------------------',
          'Requested session: ' + d.type,
          'Name: ' + d.name,
          'Email: ' + d.email,
          'Phone: ' + d.phone,
          'Preferred date or range: ' + d.date,
          '',
          'Focus / Notes: ' + d.notes,
          '',
          'Please confirm availability and next steps. This request is informational — no appointment is confirmed until we respond.'
        ].join('\n');
        out.textContent = txt; return txt;
      }

      genBtn.addEventListener('click', function(e){ e.preventDefault(); build(); });

      sendBtn.addEventListener('click', function(){
        const body = build();
        const subject = encodeURIComponent('Appointment request — ' + document.getElementById('name').value.trim());
        const mailto = 'mailto:' + '{{EMAIL}}' + '?subject=' + subject + '&body=' + encodeURIComponent(body);
        window.location.href = mailto;
      });

      // copy on double-click of summary
      out.addEventListener('dblclick', function(){ const t = out.textContent; if(!t) return; navigator.clipboard && navigator.clipboard.writeText(t).then(()=>{ const prev = out.style.background; out.style.background='#eafff0'; setTimeout(()=>out.style.background=prev,800) }).catch(()=>alert('Copy failed')) });
    })();
  </script>
